const flatten = groups => (Array.isArray(groups) ? groups : []).flatMap(group => [...(Array.isArray(group.items) ? group.items : []), ...flatten(group.childGroups)]);
const groups = [{ items: api.data.items, childGroups: api.data.childGroups }];
const mutations = flatten(groups).filter(item => item && item.key && item.modifiable !== false && !item.metadata?.managementEntry).filter(item => item.restoreDefault || (item.value !== undefined && item.value !== null && (!item.metadata?.managementAccessPolicyRequired || item.value !== ''))).map(item => item.restoreDefault ? { key: item.key, operation: 'RESTORE_DEFAULT', expectedRevision: item.revision } : { key: item.key, operation: 'SET', value: item.value, expectedRevision: item.revision });
if (!mutations.length) throw new Error('没有可提交的修改；凭据留空会保留原值。');
return { ...api, data: mutations };
